private static boolean isCasedLatinishLetter(int cp) {
    if (cp == 0x00AA || cp == 0x00BA || cp == 0x207F) {
        // ª, º, ⁿ — ordinal / superscript indicators
        return false;
    }
    int type = Character.getType(cp);
    return type == Character.UPPERCASE_LETTER || type == Character.LOWERCASE_LETTER || type == Character.TITLECASE_LETTER;
}
